const sd = $getWorkflowStaticData('global');
if (!sd.chats) sd.chats = {};

const trig = $json;
const isCallback = !!trig.callback_query;
const msg = isCallback ? trig.callback_query.message : trig.message;
const chatId = msg && msg.chat ? String(msg.chat.id) : null;
const cbData = isCallback ? String(trig.callback_query.data || '') : null;
const cbId = isCallback ? trig.callback_query.id : null;
const text = !isCallback ? String((trig.message && (trig.message.text || trig.message.caption)) || '').trim() : null;
const document = !isCallback && trig.message ? trig.message.document : null;

if (!chatId) {
  return [{ json: { skip: true, answerCallback: false, readyToCreate: false } }];
}

let state = sd.chats[chatId];
if (!state) {
  state = { step: 'start', cities: [], families: [] };
  sd.chats[chatId] = state;
}

// عائلات taxonomy_local.yaml (بدون out_of_scope — لا تُعرض على العميل).
const FAMILIES = [
  ['chem_process', 'الصناعات الكيميائية'], ['quality', 'الجودة'], ['hse', 'السلامة والصحة المهنية'],
  ['maintenance_ops', 'الصيانة والتشغيل'], ['coatings', 'الطلاء والدهانات'], ['production', 'الإنتاج'],
  ['project_controls', 'ضبط المشاريع'], ['lab_chemistry', 'المختبرات الكيميائية'],
  ['water_treatment', 'معالجة المياه'], ['supply_chain', 'سلسلة الإمداد'], ['admin', 'الإدارة والدعم'],
  ['hospitality', 'الضيافة'], ['customer_ops', 'خدمة العملاء'], ['finance_accounting', 'المالية والمحاسبة'],
  ['hr_recruiting', 'الموارد البشرية'], ['it_software', 'تقنية المعلومات'], ['logistics_ops', 'اللوجستيات'],
  ['construction_pm', 'إدارة مشاريع الإنشاء'], ['marketing_comms', 'التسويق والاتصال'],
  ['program_admin_ops', 'إدارة البرامج'], ['legal_compliance', 'الشؤون القانونية والامتثال'],
];

function familyRows(selected) {
  const rows = [];
  for (let i = 0; i < FAMILIES.length; i += 2) {
    const chunk = FAMILIES.slice(i, i + 2);
    rows.push({
      row: {
        buttons: chunk.map(([code, label]) => ({
          text: (selected.includes(code) ? '✅ ' : '') + label,
          additionalFields: { callback_data: 'fam:' + code },
        })),
      },
    });
  }
  rows.push({ row: { buttons: [{ text: '➡️ تم الاختيار', additionalFields: { callback_data: 'fam:done' } }] } });
  return rows;
}

let replyText = null;
let keyboardRows = null;
const answerCallback = isCallback;
let readyToCreate = false;

switch (state.step) {
  case 'start': {
    replyText = 'أهلًا بك في مسار 🌿\nنسعد برفقتك في البحث عن فرصة تليق بك.\nما اسمك الكريم؟';
    state.step = 'awaiting_name';
    break;
  }
  case 'awaiting_name': {
    if (text) {
      state.name = text.slice(0, 120);
      replyText = 'تشرّفنا يا ' + state.name + ' 🌿\nفي أي مدن تحب أن تكون فرصتك؟ (اكتبها مفصولة بفاصلة، مثال: الرياض، جدة)';
      state.step = 'awaiting_cities';
    } else {
      replyText = 'تفضّل، اكتب اسمك من فضلك.';
    }
    break;
  }
  case 'awaiting_cities': {
    if (text) {
      state.cities = text.split(/[,،]/).map((s) => s.trim()).filter(Boolean);
      replyText = 'رائع. اختر المجالات التي تناسب خبرتك (يمكنك اختيار أكثر من واحد)، ثم اضغط "تم الاختيار":';
      keyboardRows = familyRows(state.families);
      state.step = 'awaiting_families';
    } else {
      replyText = 'اكتب المدن التي تفضلها من فضلك.';
    }
    break;
  }
  case 'awaiting_families': {
    if (isCallback && cbData && cbData.startsWith('fam:')) {
      const code = cbData.slice(4);
      if (code === 'done') {
        if (state.families.length === 0) {
          replyText = 'اختر مجالًا واحدًا على الأقل قبل المتابعة 🌿';
          keyboardRows = familyRows(state.families);
        } else {
          replyText = 'تمام. الآن أرسل لنا سيرتك الذاتية كملف PDF من فضلك.';
          state.step = 'awaiting_cv';
        }
      } else {
        const idx = state.families.indexOf(code);
        if (idx >= 0) state.families.splice(idx, 1); else state.families.push(code);
        replyText = 'اختر المجالات المناسبة، ثم اضغط "تم الاختيار":';
        keyboardRows = familyRows(state.families);
      }
    } else {
      replyText = 'اختر من الأزرار أعلاه من فضلك، ثم اضغط "تم الاختيار".';
      keyboardRows = familyRows(state.families);
    }
    break;
  }
  case 'awaiting_cv': {
    if (document && document.file_id) {
      state.cvFileId = document.file_id;
      replyText = 'وصلتنا سيرتك الذاتية، شكرًا لك 🌿\nآخر خطوة: هل توافق أن نتقدّم لك بالفرص المناسبة نيابةً عنك؟';
      keyboardRows = [{ row: { buttons: [{ text: '✅ موافق', additionalFields: { callback_data: 'consent:yes' } }] } }];
      state.step = 'awaiting_consent';
    } else {
      replyText = 'يرجى إرسال سيرتك الذاتية كملف PDF (كمرفق ملف وليس نصًا).';
    }
    break;
  }
  case 'awaiting_consent': {
    if (isCallback && cbData === 'consent:yes') {
      readyToCreate = true;
      replyText = null;
    } else {
      replyText = 'اضغط "موافق" للمتابعة من فضلك 🌿';
      keyboardRows = [{ row: { buttons: [{ text: '✅ موافق', additionalFields: { callback_data: 'consent:yes' } }] } }];
    }
    break;
  }
  case 'done': {
    replyText = 'حسابك مفعّل بالفعل معنا، وتصلك تحديثاتك اليومية بإذن الله 🌿';
    break;
  }
  default: {
    state.step = 'awaiting_name';
    replyText = 'أهلًا بك في مسار 🌿\nما اسمك الكريم؟';
  }
}

return [{
  json: {
    skip: false,
    chatId,
    replyText,
    keyboardRows,
    answerCallback,
    callbackQueryId: cbId,
    readyToCreate,
    createPayload: readyToCreate
      ? { name: state.name, cities: state.cities, families: state.families, cvFileId: state.cvFileId }
      : null,
  },
}];

const chatId = $('موجّه المحادثة').item.json.chatId;
const path = $json.path || '';
const url = 'https://62.238.117.20.sslip.io' + path;
const text = [
  'أحسنت! بقيت خطوة أخيرة بسيطة 🌿',
  '',
  'افتح هذا الرابط من جوالك أو حاسوبك:',
  url,
  '',
  'هناك: أنشئ بريد Gmail جديدًا خاصًا بهذه الرحلة (بأي اسم يعجبك)، فعّل التحقق بخطوتين من إعدادات Google، ثم أنشئ "كلمة مرور تطبيق" (App Password) والصقها في الصفحة.',
  '',
  'بعد ذلك بإذن الله نبدأ العمل، وتصلك أخبارك كل مساء 🌙',
  'وفّقك الله وبارك في سعيك 🌿',
].join('\n');
return [{ json: { chatId, text } }];

const sd = $getWorkflowStaticData('global');
const chatId = $('موجّه المحادثة').item.json.chatId;
if (sd.chats && sd.chats[chatId]) {
  sd.chats[chatId].step = 'done';
  sd.chats[chatId].customerId = $('إنشاء العميل').item.json.customer_id;
}
return [{ json: { ok: true, customer_id: $('إنشاء العميل').item.json.customer_id } }];
